export type Hospital = GeneratedHospital;
export const hospitalsByCity: Record<string, Hospital[]> = _hospitals;

/** Title-case a single UPPERCASE string e.g. "SARITA VIHAR" → "Sarita Vihar" */
function toTitleCase(s: string): string {
  const minor = new Set(["and", "of", "the", "in", "at", "by", "for", "a"]);
  return s
    .toLowerCase()
    .split(" ")
    .map((w, i) => (i === 0 || !minor.has(w) ? w.charAt(0).toUpperCase() + w.slice(1) : w))
    .join(" ");
}

// ── 3. ALL CITIES/LOCATIONS (from new mapping) ────────────────────────────
export const allCities: string[] = getAllMainLocations().map(toTitleCase);

// ── 4. SPECIALITIES (derived from new mapping, deduplicated, Title Case) ──
export type Speciality = GeneratedSpeciality;
/** Keep specialitiesWithIds from generatedData for aaId-based URL building */
export const specialitiesWithIds: Speciality[] = _specialitiesWithIds;
/** Flat list of unique speciality names from the doctor mapping */
export const specialities: string[] = (() => {
  const set = new Set<string>();
  for (const branches of Object.values(doctorLocationMap)) {
    for (const entries of Object.values(branches)) {
      for (const e of entries) set.add(toTitleCase(e.speciality));
    }
  }
  return Array.from(set).sort();
})();

// ── 5. DOCTORS (6 900+ entries with location + speciality from new mapping)
export interface Doctor {
  name: string;
  speciality: string;
  location: string;   // main_location key (UPPERCASE)
  branch: string;     // sub_branch key (UPPERCASE), empty string for _MAIN
}
export const doctors: Doctor[] = (() => {
  const result: Doctor[] = [];
  for (const [loc, branches] of Object.entries(doctorLocationMap)) {
    for (const [branch, entries] of Object.entries(branches)) {
      for (const e of entries) {
        result.push({
          name: e.doctor_name,
          speciality: e.speciality,
          location: loc,
          branch: branch === "_MAIN" ? "" : branch,
        });
      }
    }
  }
  return result;
})();

